     */
    x?: string | number;
    /**
     * The `y` value of the point. Depending on the context , it may represents:
     * - numeric value (for `linear` y axis)
     * - timestamp value (for `datetime` y axis)
     * - y axis category value (for `category` y axis). If the type is a string, then it is a category value itself. If the type is a number, then it is the index of an element in the array of categories described in `yAxis[0].categories`
     */
    y?: string | number | null;
    /** Data label value of the point. If not specified, the y value is used. */
    label?: string | number;
    marker?: {
        /** Fill color of the marker for this point */
        color?: string;
        states?: {
            normal?: {
                enabled: boolean;
            };
        };
    };
    /**
     * Annotation displayed near this data point as a bubble with text label and optional marker.
     * Useful for highlighting specific values, events, or adding contextual notes.
     */
    annotation?: ChartPointAnnotation;
}
export interface LineSeriesLineBaseStyle {
    /**
     * Pixel width of the graph line.
     * @default 1 (for individual series).
     * For series within the range slider, values are inherited from the individual series by default.
     */
    lineWidth?: number;
    /**
     * Individual opacity for the line.
     *
     * For series within the range slider, values are inherited from the individual series by default.
     */
    opacity?: number | null;
}
export type LineSeriesInterpolation = {
    type: 'linear';
} | {
    type: 'monotone';
} | {
    type: 'cardinal';
    /**
     * Controls how tightly the curve follows the control points.
     * @minimum 0
     * @maximum 1
     * @default 0
     */
    tension?: number;
};
export type LineSeriesDataLabelPlacementPosition = 'top' | 'bottom' | 'left' | 'right';
export type LineSeriesDataLabelPlacementFallback = 'show' | 'hide';
export interface LineSeriesDataLabels extends BaseDataLabels {
    /**
     * Reference point for positioning the label. The label's `padding` is measured from it.
     * When the normal marker is disabled, `'marker-edge'` falls back to the point coordinates.
     * - `'center'`: The data point coordinates.
     * - `'marker-edge'`: The normal marker's outer edge, including its border.
     * @default 'center'
     */
    anchor?: 'center' | 'marker-edge';
    /**
     * Candidate positions relative to the point, tried in order: `auto` tries the
     * built-in order (top, bottom, left, right), an array sets the exact order to try.
     * The label box of every candidate is shifted into the plot area first; a position
     * fits when the shifted box does not cross a visible line of any line series and
     * does not overlap already placed labels (unless `allowOverlap` is set).
     * @default ['top']
     */
    placement?: 'auto' | LineSeriesDataLabelPlacementPosition[];
    /**
     * What to do when none of the `placement` positions fits: `show` draws the label
     * at the first position anyway (crossing lines and labels is allowed then),
     * `hide` hides the label.
     * @default 'show'
     */
    placementFallback?: LineSeriesDataLabelPlacementFallback;
}
export interface LineSeries<T = MeaningfulAny> extends BaseSeries, LineSeriesLineBaseStyle {
    /** Line series: points joined by line segments or a smooth curve. */
    type: typeof SERIES_TYPE.Line;
    data: LineSeriesData<T>[];
    /**
     * Options for the series data labels, appearing next to each data point.
     */
    dataLabels?: LineSeriesDataLabels;
    /** The name of the series (used in legend, tooltip etc) */
    name: string;
    /** The solid or linear-gradient color of the series. */
    color?: SeriesColor;
    /** Option for line stroke style */
    dashStyle?: DashStyle;
    /** Option for line cap style */
    linecap?: `${LineCap}`;
    /** Defines the shape to be used at the corners of the line */
    linejoin?: `${LineJoin}`;
    /** Individual series legend options. Has higher priority than legend options in widget data */
    legend?: BaseSeriesLegend & {
        symbol?: RectLegendSymbolOptions;
    };
    /** Options for the point markers of line series */
    marker?: PointMarkerOptions;
    /** Y-axis index (when using two axes) */
    yAxis?: number;
    /**
     * Specifies how null or undefined values should be handled in the series.
     *
     * - `'connect'`: Connect points across null values (skip nulls in rendering)
     * - `'zero'`: Treat null values as zero
     * - `'skip'`: Omit the data point (creates gap in line)
     * @default 'skip'
     */
    nullMode?: 'connect' | 'zero' | 'skip';
    /**
     * Configures smooth curve interpolation between data points.
     *
     * - `'linear'`: Straight line segments (default behavior)
     * - `'monotone'`: Smooth curve for data ordered monotonically by x that passes through every data point without introducing artificial extrema
     * - `'cardinal'`: Cardinal spline with optional `tension` parameter (0–1, default 0)
     *
